import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type Ref } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { cn } from '../../../lib/cn'
import { IconButton } from '../../atoms/icon-button/IconButton'
import {
  addDays,
  addMonths,
  clampDate,
  firstOfMonth,
  formatLong,
  formatMonth,
  monthGrid,
  parts,
  today as todayIso,
  weekday,
  weekStartFor,
  weekdayNames,
  type IsoDate,
} from './date-utils'

/** How a day is drawn. `single` is one picked day; the rest belong to a range. */
export type DayState = 'single' | 'start' | 'end' | 'start-end' | 'middle'

export type CalendarProps = {
  /** The picked day, 'YYYY-MM-DD'. Ignored when `dayState` is given. */
  value?: IsoDate | null
  /** A day was picked with a click, Enter or Space. */
  onSelect?: (date: IsoDate) => void
  /** The first month shown, any day in it. Controlled with `onMonthChange`. */
  month?: IsoDate
  /** The first month shown when the calendar holds it itself. @default the value's month, or today's */
  defaultMonth?: IsoDate
  onMonthChange?: (month: IsoDate) => void
  /** Earliest day that can be picked. */
  min?: IsoDate
  /** Latest day that can be picked. */
  max?: IsoDate
  /** Days that cannot be picked, e.g. weekends. Each still shows, struck through and announced as unavailable. */
  isDateDisabled?: (date: IsoDate) => boolean
  /** Draws each day for a range or any other selection. Replaces `value`. */
  dayState?: (date: IsoDate) => DayState | undefined
  /** The keyboard or the pointer moved onto a day. A range uses it to preview the band. */
  onDayEnter?: (date: IsoDate) => void
  /** Months side by side; two from the sm breakpoint up, stacked below it. @default 1 */
  numberOfMonths?: 1 | 2
  /** A BCP 47 language tag for the names and the first day of the week. @default the browser's */
  locale?: string
  /** 0 Sunday ... 6 Saturday. @default the locale's */
  weekStartsOn?: number
  /** Moves focus to the focused day when the calendar mounts (a popover opening). @default false */
  autoFocus?: boolean
  className?: string
  ref?: Ref<HTMLDivElement>
}

/**
 * A month grid you pick a day from. The grid is one tab stop: the arrow keys move a day or a week,
 * Page Up / Page Down a month (with Shift, a year), Home / End to the start or end of the week.
 * Each day is a button whose name is the full date, so a screen reader hears "Saturday,
 * 14 November 2026" rather than "14". Today carries aria-current="date" and a short bar under it.
 *
 * Contrast rows: day numbers "text.primary on surface.base"; weekday headings "text.label on
 * surface.base"; a picked day "accent.signal.indicator-ink on accent.signal.indicator" and its
 * fill "checked/on fill (accent.signal.indicator) on surface.base"; the range band "hover wash
 * text (text.primary) on accent.signal.wash over surface.base"; the ring "focus.ring on
 * surface.base". Put the calendar on surface.base, the surface those rows are measured on.
 */
export function Calendar({
  value,
  onSelect,
  month,
  defaultMonth,
  onMonthChange,
  min,
  max,
  isDateDisabled,
  dayState,
  onDayEnter,
  numberOfMonths = 1,
  locale,
  weekStartsOn,
  autoFocus = false,
  className,
  ref,
}: CalendarProps) {
  const today = todayIso()
  const start = clampDate(parts(value) ? value! : today, min, max)
  const [internalMonth, setInternalMonth] = useState(() => firstOfMonth(defaultMonth ?? start))
  const shown = firstOfMonth(month ?? internalMonth)
  const setShown = (next: IsoDate) => {
    if (month === undefined) setInternalMonth(firstOfMonth(next))
    onMonthChange?.(firstOfMonth(next))
  }
  const [focused, setFocused] = useState<IsoDate>(start)
  // Only a key press moves real focus; a re-render from outside must not steal it.
  const moveFocus = useRef(autoFocus)
  const grid = useRef<HTMLDivElement>(null)
  const id = useId()

  const weekStart = weekStartsOn ?? weekStartFor(locale)
  const names = useMemo(() => weekdayNames(weekStart, locale), [weekStart, locale])
  const months = Array.from({ length: numberOfMonths }, (_, i) => addMonths(shown, i))
  const lastShown = months[months.length - 1]
  const inView = (date: IsoDate) => date.slice(0, 7) >= shown.slice(0, 7) && date.slice(0, 7) <= lastShown.slice(0, 7)
  // The roving tab stop has to be a day that is on screen.
  const tabStop = inView(focused) ? focused : inView(start) ? start : shown

  const disabled = (date: IsoDate) => (min !== undefined && date < min) || (max !== undefined && date > max) || !!isDateDisabled?.(date)
  const stateOf = (date: IsoDate): DayState | undefined => (dayState ? dayState(date) : value === date ? 'single' : undefined)

  useEffect(() => {
    if (!moveFocus.current) return
    moveFocus.current = false
    grid.current?.querySelector<HTMLButtonElement>(`[data-date="${tabStop}"]`)?.focus()
  }, [tabStop])

  const go = (date: IsoDate) => {
    const next = clampDate(date, min, max)
    moveFocus.current = true
    setFocused(next)
    if (!inView(next)) setShown(next < shown ? next : addMonths(next, -(numberOfMonths - 1)))
    onDayEnter?.(next)
  }

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, date: IsoDate) => {
    const offset = (weekday(date) - weekStart + 7) % 7
    const moves: Record<string, () => IsoDate> = {
      ArrowLeft: () => addDays(date, -1),
      ArrowRight: () => addDays(date, 1),
      ArrowUp: () => addDays(date, -7),
      ArrowDown: () => addDays(date, 7),
      PageUp: () => addMonths(date, event.shiftKey ? -12 : -1),
      PageDown: () => addMonths(date, event.shiftKey ? 12 : 1),
      Home: () => addDays(date, -offset),
      End: () => addDays(date, 6 - offset),
    }
    const move = moves[event.key]
    if (!move) return
    event.preventDefault()
    go(move())
  }

  const pick = (date: IsoDate) => {
    if (disabled(date)) return
    setFocused(date)
    onSelect?.(date)
  }

  const canPrev = !min || addMonths(shown, -1).slice(0, 7) >= min.slice(0, 7)
  const canNext = !max || addMonths(lastShown, 1).slice(0, 7) <= max.slice(0, 7)

  return (
    <div ref={ref} className={cn('inline-flex flex-col gap-3 font-body', className)}>
      <div className="flex items-center justify-between gap-2">
        <IconButton label="Previous month" variant="ghost" size="sm" disabled={!canPrev} onClick={() => setShown(addMonths(shown, -1))}>
          <ChevronLeft />
        </IconButton>
        {/* Announced when it changes, so Page Down is heard as "December 2026". */}
        <p aria-live="polite" className="flex-1 text-center font-display text-sm font-semibold uppercase tracking-[0.12em] text-[var(--color-text-primary)]">
          {months.map(m => formatMonth(m, locale)).join(' – ')}
        </p>
        <IconButton label="Next month" variant="ghost" size="sm" disabled={!canNext} onClick={() => setShown(addMonths(shown, 1))}>
          <ChevronRight />
        </IconButton>
      </div>
      <div ref={grid} className="flex flex-col gap-5 sm:flex-row sm:gap-6">
        {months.map(m => {
          const captionId = `${id}-${m}`
          const thisMonth = m.slice(0, 7)
          return (
            <div key={m} className="flex flex-col gap-1">
              {numberOfMonths > 1 ? (
                <p id={captionId} className="text-center font-mono text-[11px] font-semibold uppercase tracking-[0.16em] text-[var(--color-text-label)]">
                  {formatMonth(m, locale)}
                </p>
              ) : (
                <span id={captionId} className="sr-only">
                  {formatMonth(m, locale)}
                </span>
              )}
              <table role="grid" aria-labelledby={captionId} className="border-collapse">
                <thead>
                  <tr>
                    {names.map(name => (
                      <th key={name.long} scope="col" abbr={name.long} className="h-8 w-9 sm:w-10 text-center font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-[var(--color-text-label)]">
                        {name.short}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {monthGrid(m, weekStart)
                    .filter(week => week.some(date => date.slice(0, 7) === thisMonth))
                    .map(week => (
                      <tr key={week[0]}>
                        {week.map(date => {
                          if (date.slice(0, 7) !== thisMonth) return <td key={date} aria-hidden="true" className="h-9 w-9 sm:h-10 sm:w-10" />
                          const state = stateOf(date)
                          const off = disabled(date)
                          const filled = state === 'single' || state === 'start' || state === 'end' || state === 'start-end'
                          return (
                            <td
                              key={date}
                              role="gridcell"
                              aria-selected={state ? true : undefined}
                              className={cn(
                                'relative h-9 w-9 p-0 sm:h-10 sm:w-10',
                                // The band runs behind the days between the ends, and half into each end.
                                state === 'middle' && 'bg-[var(--color-accent-signal-wash)]',
                                state === 'start' && 'bg-[linear-gradient(to_right,transparent_50%,var(--color-accent-signal-wash)_50%)]',
                                state === 'end' && 'bg-[linear-gradient(to_left,transparent_50%,var(--color-accent-signal-wash)_50%)]'
                              )}
                            >
                              <button
                                type="button"
                                data-date={date}
                                tabIndex={date === tabStop ? 0 : -1}
                                aria-label={`${formatLong(date, locale)}${off ? ', unavailable' : ''}`}
                                aria-current={date === today ? 'date' : undefined}
                                aria-disabled={off || undefined}
                                onClick={() => pick(date)}
                                onKeyDown={event => onKeyDown(event, date)}
                                onFocus={() => setFocused(date)}
                                onPointerEnter={() => !off && onDayEnter?.(date)}
                                className={cn(
                                  'group relative flex h-9 w-9 items-center sm:h-10 sm:w-10 justify-center text-sm tabular-nums transition-control',
                                  'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[var(--color-focus-ring)]',
                                  off
                                    ? 'cursor-not-allowed text-[var(--component-control-text-disabled)] line-through'
                                    : cn('cursor-pointer text-[var(--color-text-primary)]', !filled && 'hover:bg-[var(--color-accent-signal-wash)]'),
                                  date === today && 'font-semibold',
                                  // On the accent square the ring would vanish: it takes the square's ink.
                                  filled && 'focus-visible:outline-[var(--color-accent-signal-indicator-ink)]'
                                )}
                              >
                                {filled ? <span aria-hidden="true" className="bevel-sm absolute inset-1 bg-[var(--color-accent-signal-indicator)]" /> : null}
                                <span className={cn('relative', filled && 'font-semibold text-[var(--color-accent-signal-indicator-ink)]')}>
                                  {parts(date)!.day}
                                </span>
                                {date === today ? (
                                  <span
                                    aria-hidden="true"
                                    className={cn(
                                      'absolute bottom-1.5 left-1/2 h-0.5 w-3 -translate-x-1/2',
                                      filled ? 'bg-[var(--color-accent-signal-indicator-ink)]' : 'bg-[var(--color-accent-signal-indicator)]'
                                    )}
                                  />
                                ) : null}
                              </button>
                            </td>
                          )
                        })}
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          )
        })}
      </div>
    </div>
  )
}

// Calendar dates as plain 'YYYY-MM-DD' strings. A date here has no time and no time zone: every
// calculation runs in UTC, so a day never shifts because the reader's clock is in another zone or
// crosses a daylight-saving change.

export type IsoDate = string

const ISO = /^(\d{4})-(\d{2})-(\d{2})$/

const toUtc = (y: number, m: number, d: number) => new Date(Date.UTC(y, m - 1, d))
const fromUtc = (date: Date): IsoDate => date.toISOString().slice(0, 10)

/** { year, month (1-12), day } for a valid ISO date, otherwise null. */
export function parts(iso: string | null | undefined): { year: number; month: number; day: number } | null {
  const match = iso ? ISO.exec(iso) : null
  if (!match) return null
  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])]
  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) return null
  return { year, month, day }
}

export const isValidDate = (iso: string | null | undefined) => parts(iso) !== null

export function makeDate(year: number, month: number, day: number): IsoDate {
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

export const daysInMonth = (year: number, month: number) => new Date(Date.UTC(year, month, 0)).getUTCDate()

export function addDays(iso: IsoDate, days: number): IsoDate {
  const p = parts(iso)!
  return fromUtc(toUtc(p.year, p.month, p.day + days))
}

/** Same day in another month, pulled back to that month's last day when it has fewer. */
export function addMonths(iso: IsoDate, months: number): IsoDate {
  const p = parts(iso)!
  const index = p.year * 12 + (p.month - 1) + months
  const year = Math.floor(index / 12)
  const month = (index % 12) + 1
  return makeDate(year, month, Math.min(p.day, daysInMonth(year, month)))
}

/** 0 = Sunday ... 6 = Saturday. */
export const weekday = (iso: IsoDate) => {
  const p = parts(iso)!
  return toUtc(p.year, p.month, p.day).getUTCDay()
}

export const firstOfMonth = (iso: IsoDate) => {
  const p = parts(iso)!
  return makeDate(p.year, p.month, 1)
}

/** ISO strings compare correctly as text. */
export const compareDates = (a: IsoDate, b: IsoDate) => (a < b ? -1 : a > b ? 1 : 0)

export function clampDate(iso: IsoDate, min?: IsoDate, max?: IsoDate): IsoDate {
  if (min && iso < min) return min
  if (max && iso > max) return max
  return iso
}

/** Today in the reader's own time zone: the date their wall calendar shows. */
export function today(now = new Date()): IsoDate {
  return makeDate(now.getFullYear(), now.getMonth() + 1, now.getDate())
}

/** The first day of the week for a locale: 1 Monday (most of the world), 0 Sunday (US, Canada,
 *  Japan...), 6 Saturday. Read from Intl where the browser has it. */
export function weekStartFor(locale?: string): number {
  try {
    const info = new Intl.Locale(locale ?? navigator.language) as Intl.Locale & {
      weekInfo?: { firstDay: number }
      getWeekInfo?: () => { firstDay: number }
    }
    const firstDay = info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay
    if (firstDay) return firstDay % 7
  } catch {
    // An unknown locale tag: fall through to Monday.
  }
  return 1
}

/** The six weeks a month grid shows, each seven ISO dates, starting on `weekStart`. */
export function monthGrid(month: IsoDate, weekStart: number): IsoDate[][] {
  const first = firstOfMonth(month)
  const start = addDays(first, -((weekday(first) - weekStart + 7) % 7))
  return Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, d) => addDays(start, w * 7 + d)))
}

const formatter = (locale: string | undefined, options: Intl.DateTimeFormatOptions) =>
  new Intl.DateTimeFormat(locale, { timeZone: 'UTC', ...options })

const asDate = (iso: IsoDate) => {
  const p = parts(iso)!
  return toUtc(p.year, p.month, p.day)
}

/** "November 2026". */
export const formatMonth = (iso: IsoDate, locale?: string) => formatter(locale, { month: 'long', year: 'numeric' }).format(asDate(iso))

/** "Saturday, 14 November 2026": what a screen reader hears for a day. */
export const formatLong = (iso: IsoDate, locale?: string) =>
  formatter(locale, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(asDate(iso))

/** Weekday column headings from `weekStart`: short ("Mo") and long ("Monday"). */
export function weekdayNames(weekStart: number, locale?: string) {
  // 2023-01-01 was a Sunday.
  return Array.from({ length: 7 }, (_, i) => {
    const date = toUtc(2023, 1, 1 + ((weekStart + i) % 7))
    return {
      short: formatter(locale, { weekday: 'short' }).format(date).slice(0, 2),
      long: formatter(locale, { weekday: 'long' }).format(date),
    }
  })
}

export type SegmentKind = 'day' | 'month' | 'year'

/** The order of day, month and year for a locale, and the separator between them: en-GB gives
 *  day / month / year with '/', en-US month / day / year, de day.month.year. */
export function segmentOrder(locale?: string): { order: SegmentKind[]; separator: string } {
  const formatted = formatter(locale, { day: '2-digit', month: '2-digit', year: 'numeric' }).formatToParts(toUtc(2026, 11, 14))
  const order = formatted.filter(part => part.type === 'day' || part.type === 'month' || part.type === 'year').map(part => part.type as SegmentKind)
  const separator = formatted.find(part => part.type === 'literal')?.value.trim() || '/'
  return { order: order.length === 3 ? order : ['day', 'month', 'year'], separator }
}

import { Fragment, useEffect, useMemo, useRef, useState, type KeyboardEvent, type ReactNode, type Ref } from 'react'
import { cn } from '../../../lib/cn'
import { daysInMonth, isValidDate, makeDate, parts, segmentOrder, today, type IsoDate, type SegmentKind } from './date-utils'

type Segments = Record<SegmentKind, string>

const EMPTY: Segments = { day: '', month: '', year: '' }
const LIMITS: Record<SegmentKind, { min: number; max: number; width: number; placeholder: string; name: string }> = {
  day: { min: 1, max: 31, width: 2, placeholder: 'dd', name: 'Day' },
  month: { min: 1, max: 12, width: 2, placeholder: 'mm', name: 'Month' },
  year: { min: 1, max: 9999, width: 4, placeholder: 'yyyy', name: 'Year' },
}

const fromIso = (iso: string | undefined): Segments => {
  const p = parts(iso)
  return p ? { day: String(p.day).padStart(2, '0'), month: String(p.month).padStart(2, '0'), year: String(p.year).padStart(4, '0') } : EMPTY
}
const toIso = (s: Segments): IsoDate | '' => {
  if (!s.day || !s.month || s.year.length !== 4) return ''
  const iso = makeDate(Number(s.year), Number(s.month), Number(s.day))
  return isValidDate(iso) ? iso : ''
}

export type DateFieldProps = {
  /** 'YYYY-MM-DD', or '' for no date. Controlled with `onValueChange`. */
  value?: IsoDate | ''
  defaultValue?: IsoDate | ''
  /** A whole, real date was typed, or the field was emptied (''). A half-typed date does not fire. */
  onValueChange?: (value: IsoDate | '') => void
  /** Earliest allowed date. A typed date before it marks the field invalid. */
  min?: IsoDate
  /** Latest allowed date. A typed date after it marks the field invalid. */
  max?: IsoDate
  /** A typed date this returns true for marks the field invalid. */
  isDateDisabled?: (date: IsoDate) => boolean
  /** A BCP 47 language tag. Sets the order of day, month and year and the separator. @default the browser's */
  locale?: string
  /** Required. The field's accessible name. Inside a FormField, FormField sets it. */
  label: string
  disabled?: boolean
  invalid?: boolean
  required?: boolean
  /** Submits the ISO value with a form, through a hidden input. */
  name?: string
  id?: string
  'aria-describedby'?: string
  /** Sits inside the field's border, after the segments: DatePicker's calendar button. */
  trailing?: ReactNode
  /** No border, fill, padding or ring of its own, for two or more fields inside one border
   *  (DateRangePicker). The container then draws them. @default false */
  bare?: boolean
  className?: string
  ref?: Ref<HTMLDivElement>
}

/**
 * A date typed in three segments, in the order the locale writes them. Each segment is a
 * spinbutton: type digits and it moves on by itself once the segment is full or no further digit
 * could fit ("4" in the day is the 4th), the arrow keys step it, Backspace clears it. Left and
 * Right move between segments, and typing the separator jumps ahead. It cannot hold a string
 * that is not a date.
 *
 * Contrast rows: segments "text.primary on control fill" (component.control.text.rest); the
 * empty placeholders "control placeholder text on control fill"; the separators the same; the
 * border "control border on control fill"; the ring "focus.ring on surface.base".
 */
export function DateField({
  value,
  defaultValue = '',
  onValueChange,
  min,
  max,
  isDateDisabled,
  locale,
  label,
  disabled = false,
  invalid = false,
  required,
  name,
  id,
  'aria-describedby': describedBy,
  trailing,
  bare = false,
  className,
  ref,
}: DateFieldProps) {
  const [segments, setSegments] = useState<Segments>(() => fromIso(value ?? defaultValue))
  // What this field last reported, so a controlled value echoing it back does not reset the
  // segments someone is halfway through typing.
  const reported = useRef<string>(toIso(segments))
  const buffer = useRef('')
  const refs = useRef<Partial<Record<SegmentKind, HTMLSpanElement | null>>>({})
  const { order, separator } = useMemo(() => segmentOrder(locale), [locale])

  useEffect(() => {
    if (value === undefined || value === reported.current) return
    reported.current = value
    setSegments(fromIso(value))
  }, [value])

  const iso = toIso(segments)
  const complete = order.every(kind => segments[kind] !== '') && segments.year.length === 4
  const outOfRange = iso !== '' && ((min !== undefined && iso < min) || (max !== undefined && iso > max) || !!isDateDisabled?.(iso))
  const isInvalid = invalid || outOfRange || (complete && iso === '')

  const update = (next: Segments) => {
    setSegments(next)
    const out = toIso(next)
    if (out !== reported.current) {
      reported.current = out
      onValueChange?.(out)
    }
  }

  const focusSegment = (kind: SegmentKind | undefined) => kind && refs.current[kind]?.focus()
  const neighbour = (kind: SegmentKind, step: 1 | -1) => order[order.indexOf(kind) + step]

  const maxFor = (kind: SegmentKind, s: Segments) =>
    kind === 'day' && s.month && s.year.length === 4 ? daysInMonth(Number(s.year), Number(s.month)) : LIMITS[kind].max

  const typeDigit = (kind: SegmentKind, digit: string) => {
    const limit = LIMITS[kind]
    const next = buffer.current + digit
    if (kind === 'year') {
      buffer.current = next.length >= 4 ? '' : next
      update({ ...segments, year: next.slice(-4).padStart(next.length >= 4 ? 4 : next.length, '0') })
      if (next.length >= 4) focusSegment(neighbour(kind, 1))
      return
    }
    const max = maxFor(kind, segments)
    const number = Number(next)
    if (next.length === 2 && number === 0) return
    // Full, or no second digit could make a valid number ("4" in a day, "2" in a month).
    if (next.length >= 2 || Number(`${next}0`) > max) {
      buffer.current = ''
      update({ ...segments, [kind]: String(Math.min(Math.max(number, limit.min), max)).padStart(2, '0') })
      focusSegment(neighbour(kind, 1))
    } else {
      buffer.current = next
      update({ ...segments, [kind]: next })
    }
  }

  const step = (kind: SegmentKind, by: 1 | -1) => {
    const limit = LIMITS[kind]
    const current = segments[kind]
    const now = parts(today())!
    const max = maxFor(kind, segments)
    let next: number
    if (!current) next = kind === 'year' ? now.year : kind === 'month' ? now.month : now.day
    else {
      next = Number(current) + by
      if (kind !== 'year') next = next > max ? limit.min : next < limit.min ? max : next
    }
    buffer.current = ''
    update({ ...segments, [kind]: String(Math.max(next, limit.min)).padStart(limit.width, '0') })
  }

  const onKeyDown = (event: KeyboardEvent<HTMLSpanElement>, kind: SegmentKind) => {
    if (disabled) return
    const key = event.key
    if (/^\d$/.test(key)) {
      event.preventDefault()
      typeDigit(kind, key)
    } else if (key === 'ArrowUp' || key === 'ArrowDown') {
      event.preventDefault()
      step(kind, key === 'ArrowUp' ? 1 : -1)
    } else if (key === 'ArrowLeft' || key === 'ArrowRight') {
      event.preventDefault()
      focusSegment(neighbour(kind, key === 'ArrowLeft' ? -1 : 1))
    } else if (key === 'Backspace' || key === 'Delete') {
      event.preventDefault()
      buffer.current = ''
      if (segments[kind]) update({ ...segments, [kind]: '' })
      else if (key === 'Backspace') focusSegment(neighbour(kind, -1))
    } else if (key === separator || key === '/' || key === '.' || key === '-' || key === ' ') {
      event.preventDefault()
      buffer.current = ''
      focusSegment(neighbour(kind, 1))
    }
  }

  return (
    <div
      ref={ref}
      id={id}
      role="group"
      aria-label={label}
      aria-describedby={describedBy}
      aria-invalid={isInvalid || undefined}
      aria-disabled={disabled || undefined}
      data-disabled={disabled ? '' : undefined}
      className={cn(
        'flex items-center gap-1 font-body text-sm tabular-nums text-[var(--component-control-text-rest)]',
        bare
          ? cn('w-auto', isInvalid && 'text-[var(--color-accent-hostile-text)]')
          : cn(
              'w-full rounded-[var(--shape-radius,0px)] border px-3 transition-control',
              'h-[var(--component-control-height-md)] bg-[var(--component-control-fill-rest)]',
              isInvalid ? 'border-[var(--component-control-border-invalid)]' : 'border-[var(--component-control-border-rest)] hover:border-[var(--component-control-border-hover)]',
              'has-[[role=spinbutton]:focus-visible]:outline-2 has-[[role=spinbutton]:focus-visible]:outline-offset-2 has-[[role=spinbutton]:focus-visible]:outline-[var(--color-focus-ring)]',
              disabled && 'bg-[var(--component-control-fill-disabled)]'
            ),
        disabled && 'text-[var(--component-control-text-disabled)]',
        className
      )}
    >
      {order.map((kind, i) => {
        const limit = LIMITS[kind]
        const text = segments[kind]
        return (
          <Fragment key={kind}>
            {i > 0 ? (
              <span aria-hidden="true" className="text-[var(--component-control-text-placeholder)]">
                {separator}
              </span>
            ) : null}
            <span
              ref={node => {
                refs.current[kind] = node
              }}
              role="spinbutton"
              tabIndex={disabled ? -1 : 0}
              inputMode="numeric"
              aria-label={limit.name}
              aria-valuemin={limit.min}
              aria-valuemax={kind === 'day' ? maxFor('day', segments) : limit.max}
              aria-valuenow={text ? Number(text) : undefined}
              aria-valuetext={text ? text : 'Empty'}
              aria-required={required || undefined}
              aria-disabled={disabled || undefined}
              onKeyDown={event => onKeyDown(event, kind)}
              onFocus={() => {
                buffer.current = ''
              }}
              onBlur={() => {
                // A lone digit left behind ("4" in the month) is padded when focus leaves.
                if (buffer.current && kind !== 'year') update({ ...segments, [kind]: buffer.current.padStart(2, '0') })
                buffer.current = ''
              }}
              className={cn(
                'rounded-[2px] px-0.5 text-center outline-none caret-transparent',
                kind === 'year' ? 'min-w-[4ch]' : 'min-w-[2ch]',
                'focus:bg-[var(--color-accent-signal-indicator)] focus:text-[var(--color-accent-signal-indicator-ink)]',
                !text && 'text-[var(--component-control-text-placeholder)]'
              )}
            >
              {text || limit.placeholder}
            </span>
          </Fragment>
        )
      })}
      {name ? <input type="hidden" name={name} value={iso} /> : null}
      {trailing ? <span className="ml-auto flex items-center">{trailing}</span> : null}
    </div>
  )
}

import { useState } from 'react'
import { Popover as RadixPopover } from 'radix-ui'
import { CalendarDays } from 'lucide-react'
import { cn } from '../../../lib/cn'
import { Button } from '../../atoms/button/Button'
import { IconButton } from '../../atoms/icon-button/IconButton'
import { Calendar } from './Calendar'
import { DateField, type DateFieldProps } from './DateField'
import { formatLong, isValidDate, today as todayIso, type IsoDate } from './date-utils'

export type DatePickerProps = Omit<DateFieldProps, 'trailing' | 'bare'> & {
  /** 0 Sunday ... 6 Saturday. @default the locale's */
  weekStartsOn?: number
  /** Adds a Today button under the calendar when today can be picked. @default true */
  showToday?: boolean
}

/**
 * One date: type it in the segmented field, or open the calendar from the button inside it.
 * Picking a day fills the field, closes the calendar and puts focus back on the button. Escape
 * closes it without a change. The value is a plain 'YYYY-MM-DD' string, with no time and no time
 * zone, so it means the same day for everyone who reads it.
 *
 * Range, time and presets are separate add-ons on top of this (DateRangePicker, TimeField,
 * DatePresets), each installed on its own.
 *
 * Contrast rows: the field's (see DateField), the calendar's (see Calendar), and the popover's
 * edge "decorative" hairline-strong; the calendar sits on surface.base.
 */
export function DatePicker({
  value,
  defaultValue = '',
  onValueChange,
  weekStartsOn,
  showToday = true,
  disabled,
  locale,
  label,
  ref,
  ...field
}: DatePickerProps) {
  const [internal, setInternal] = useState<IsoDate | ''>(defaultValue)
  const current = value ?? internal
  const [open, setOpen] = useState(false)
  const set = (next: IsoDate | '') => {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }
  const today = todayIso()
  const todayAllowed =
    (!field.min || today >= field.min) && (!field.max || today <= field.max) && !field.isDateDisabled?.(today)
  const pick = (date: IsoDate) => {
    set(date)
    setOpen(false)
  }

  return (
    <RadixPopover.Root open={open && !disabled} onOpenChange={setOpen}>
      <RadixPopover.Anchor asChild>
        <DateField
          ref={ref}
          {...field}
          label={label}
          locale={locale}
          disabled={disabled}
          value={current}
          onValueChange={set}
          trailing={
            <RadixPopover.Trigger asChild>
              <IconButton
                label={isValidDate(current) ? `Choose date, ${formatLong(current, locale)}` : 'Choose date'}
                variant="ghost"
                size="sm"
                disabled={disabled}
                className="-mr-2"
              >
                <CalendarDays />
              </IconButton>
            </RadixPopover.Trigger>
          }
        />
      </RadixPopover.Anchor>
      <RadixPopover.Portal>
        <RadixPopover.Content
          side="bottom"
          align="start"
          sideOffset={6}
          collisionPadding={8}
          aria-label={`${label}, calendar`}
          // The calendar puts focus on the picked day (or today) itself.
          onOpenAutoFocus={event => event.preventDefault()}
          className={cn(
            'z-50 border border-[var(--color-border-hairline-strong)] bg-[var(--color-surface-base)] p-3',
            'crosshair anim-popover'
          )}
        >
          <Calendar
            value={isValidDate(current) ? current : null}
            onSelect={pick}
            min={field.min}
            max={field.max}
            isDateDisabled={field.isDateDisabled}
            locale={locale}
            weekStartsOn={weekStartsOn}
            autoFocus
          />
          {showToday && todayAllowed ? (
            <div className="mt-3 flex justify-end border-t border-[var(--color-border-hairline)] pt-3">
              <Button variant="secondary" size="sm" onClick={() => pick(today)}>
                Today
              </Button>
            </div>
          ) : null}
        </RadixPopover.Content>
      </RadixPopover.Portal>
    </RadixPopover.Root>
  )
}
